function validateBundle(b){if(b?.kind==='small-machines')return {set:validateSet(b),scenes};if(!b||b.kind!=='small-machines-session'||b.version!==1||!Array.isArray(b.scenes)||b.scenes.length!==4)throw Error('Keine Small-Machines-Setdatei.');validateSet(b.set);for(const s of b.scenes)if(s!==null){if(typeof s.name!=='string'||s.name.length>60)throw Error('Ungültiger Szenenname');validateSet(s.set);}return b;}
