const names=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'],noteName=n=>n===null?'·':names[n%12]+(Math.floor(n/12)-1);
function toast(t){$('rack-toast').textContent=t;$('rack-toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('rack-toast').classList.remove('visible'),4500);}
function persist(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{if(!db){$('rack-save-status').textContent='Bitte Set exportieren: Browserspeicher nicht verfügbar.';return;}try{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(bundle(),'session');tx.oncomplete=()=>$('rack-save-status').textContent='Set und Szenen sind auf diesem Gerät gespeichert.';tx.onerror=()=>$('rack-save-status').textContent='Speichern fehlgeschlagen. Bitte Set exportieren.';}catch{$('rack-save-status').textContent='Bitte Set exportieren.';}},450);}
function send(type,data={}){node?.port.postMessage({type,...data});}
