function updateTransport(){$('rack-play-icon').textContent=playing?'Ⅱ':'▶';$('rack-play-label').textContent=playing?'Stop':audioReady?'Spielen':'Einschalten & spielen';$('rack-play').classList.toggle('playing',playing);$('display-title').textContent=set.paula.name.replace(/^\d+ · /,'').toUpperCase();$('display-status').textContent=state.error?'MACHINE STOPPED':playing?'SID + PAULA · ONE CLOCK':'4 × 8-BIT PCM · PAULA INSPIRED';$('display-step').textContent=playing?`BAR ${String(state.bar).padStart(2,'0')} · ${String(state.position+1).padStart(2,'0')}/16`:'READY.';}
