function sampleFor(i){const c=set.paula.channels[i];return c.sample.startsWith('custom')?{...set.paula.custom[+c.sample.slice(-1)],id:c.sample}:SAMPLE_BANK.find(s=>s.id===c.sample);}
let sampleCategory='Alle',previewNode=null,previewSerial=0,previewId=null;
