function stopPreview(){previewSerial++;if(previewNode){previewNode.onended=null;try{previewNode.stop();}catch{}previewNode.disconnect();previewNode=null;}previewId=null;document.querySelectorAll('[data-audition]').forEach(b=>{b.setAttribute('aria-pressed','false');b.textContent='▶ Vorhören';});}
async function audition(id){if(previewId===id){stopPreview();return;}stopPreview();if(playing||recording){toast('Zum Vorhören zuerst Transport und Aufnahme stoppen.');return;}const serial=previewSerial,sample=catalog().find(s=>s.id===id);if(!sample)return;try{await audio();if(serial!==previewSerial||playing||recording)return;const pcm=previewPCM(sample,audioContext.sampleRate),buffer=audioContext.createBuffer(1,pcm.length,audioContext.sampleRate);buffer.copyToChannel(pcm,0);const source=audioContext.createBufferSource();source.buffer=buffer;source.connect(analyser);previewNode=source;previewId=id;source.onended=()=>{if(previewNode===source)stopPreview();};source.start();document.querySelectorAll('[data-audition]').forEach(b=>{const active=b.dataset.audition===id;b.setAttribute('aria-pressed',String(active));b.textContent=active?'■ Stop':'▶ Vorhören';});}catch(e){stopPreview();toast(e.message);}}
function renderLibrary(){const samples=findSamples(catalog(),$('sample-search').value,sampleCategory);$('sample-target').value=selected;$('sample-categories').innerHTML=['Alle',...SAMPLE_CATEGORIES].map(c=>`<button data-category="${c}" aria-pressed="${c===sampleCategory}">${c}</button>`).join('');$('sample-results').textContent=`${samples.length} Sounds · Laden in Kanal ${selected+1}`;$('sample-catalog').innerHTML=samples.length?samples.map(s=>`<article class="catalog-sound ${set.paula.channels[selected].sample===s.id?'loaded':''}"><div class="catalog-meta"><span>${s.category}</span><span>${s.loop?'LOOP':(s.pcm.length/s.rate).toFixed(2)+' s'} · ${noteName(s.root)}</span></div><h4>${esc(s.name.replace(/^\d+ · /,''))}</h4><p>${esc(s.description)}</p><div class="catalog-actions"><button data-audition="${s.id}" aria-pressed="${previewId===s.id}" aria-label="${esc(s.name)} vorhören">${previewId===s.id?'■ Stop':'▶ Vorhören'}</button><button data-load-sample="${s.id}" aria-label="${esc(s.name)} in Kanal ${selected+1} laden">${set.paula.channels[selected].sample===s.id?'Geladen ✓':'Laden →'}</button></div></article>`).join(''):'<p class="catalog-empty">Kein Sound gefunden. Versuche einen anderen Suchbegriff oder eine andere Kategorie.</p>';}
