function renderMix(){$('crossfade').value=Math.round(set.mix.crossfade*100);$('crossfade-value').textContent=set.mix.crossfade<=.01?'SID ONLY':set.mix.crossfade>=.99?'PAULA ONLY':`${Math.round((1-set.mix.crossfade)*100)} / ${Math.round(set.mix.crossfade*100)}`;for(const k of ['master','tone']){$(k).value=k==='master'?Math.round(set.mix[k]*100):set.mix[k];$(k+'-value').textContent=$(k).value+'%';}}
