const held=new Map();let holdOrder=0;function paintKeys(){document.querySelectorAll('#paula-keyboard .key').forEach(k=>k.classList.toggle('pressed',[...held.values()].some(n=>n.note===+k.dataset.note)));document.querySelectorAll('[data-trigger]').forEach(b=>b.classList.toggle('active',[...held.values()].some(n=>n.voice===+b.dataset.trigger)));}
async function press(token,note,voice=selected){stopPreview();if(held.has(token))return;const item={voice,note,order:++holdOrder};held.set(token,item);paintKeys();try{await audio();if(held.get(token)===item)send('noteOn',{voice,note});}catch(e){held.delete(token);paintKeys();toast(e.message);}}
