$('paula-keyboard').onpointerdown=e=>{const b=e.target.closest('.key');if(!b)return;e.preventDefault();b.setPointerCapture(e.pointerId);press('p'+e.pointerId,+b.dataset.note);};for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('paula-keyboard').addEventListener(ev,e=>release('p'+e.pointerId));for(const [id,dir]of [['paula-oct-down',-1],['paula-oct-up',1]])$(id).onclick=()=>{releaseAll();octave=Math.max(1,Math.min(6,octave+dir));renderKeyboard();};
const keyMap={a:0,w:1,s:2,e:3,d:4,f:5,t:6,g:7,y:8,z:8,h:9,u:10,j:11,k:12};window.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();$('panic').click();return;}if(e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();if(!e.repeat)$('rack-play').click();return;}if(/^[1-4]$/.test(e.key)&&!e.repeat){launchScene(+e.key-1);return;}const k=e.key.toLowerCase();if(k in keyMap&&!e.repeat){e.preventDefault();press('k'+k,(octave+1)*12+keyMap[k]);}};window.onkeyup=e=>release('k'+e.key.toLowerCase());window.addEventListener('blur',()=>{releaseAll();stopPreview();});document.addEventListener('visibilitychange',()=>{if(document.hidden){releaseAll();stopPreview();}});
