function setTempo(value){set.bpm=Math.round(Math.max(40,Math.min(220,value||112)));set.sid.bpm=set.paula.bpm=set.bpm;local.setTempo(set.bpm);send('tempo',{bpm:set.bpm});$('rack-tempo').value=set.bpm;persist();}$('rack-tempo').onchange=()=>setTempo(+$('rack-tempo').value);let taps=[];$('tap-tempo').onclick=()=>{const now=performance.now();if(taps.length&&now-taps.at(-1)>2000)taps=[];taps.push(now);taps=taps.slice(-6);if(taps.length>1)setTempo(60000*(taps.length-1)/(now-taps[0]));};
$('rack-play').onclick=async()=>{stopPreview();try{await audio();releaseAll();if(playing){send('stop');playing=false;pendingScene=null;}else{send('play');playing=true;}updateTransport();renderScenes();}catch(e){toast(e.message);}};
$('rack-stop').onclick=()=>{stopPreview();releaseAll();send('stop');local.stop();playing=false;pendingScene=null;updateTransport();renderScenes();};$('panic').onclick=()=>{stopPreview();releaseAll();send('panic');local.panic();state=local.snapshot();playing=false;pendingScene=null;updateState();renderScenes();};
function selectPaula(i){stopPreview();if(!Number.isInteger(i)||i<0||i>=PAULA_PRESETS.length)return;releaseAll();set.paula=freshPaula(i);set.paula.bpm=set.bpm;updatePaula(true,true);activeScene=null;renderAll();toast('Paula-Klangwelt geladen.');}$('paula-preset').onchange=e=>selectPaula(Number(e.target.value));$('live-paula-preset').onchange=e=>selectPaula(Number(e.target.value));
$('live-sid-preset').onchange=e=>{const i=Number(e.target.value);if(!Number.isInteger(i)||i<0||i>=PRESETS.length)return;set.sid=freshProject(i);set.sid.bpm=set.bpm;local.sid.setProject(set.sid);local.sid.load(set.sid.source);send('sid',{project:set.sid,reload:true});renderLive();persist();};
$('take-sid').onclick=()=>{try{const raw=localStorage.getItem('sid65-project-v1');if(!raw)throw Error('Im SID-Studio ist noch kein gespeichertes Muster vorhanden.');set.sid=clone(validateProject(JSON.parse(raw)));set.sid.bpm=set.bpm;local.sid.setProject(set.sid);local.sid.load(set.sid.source);send('sid',{project:set.sid,reload:true});renderLive();persist();toast('SID-Muster übernommen.');}catch(e){toast(e.message);}};
$('live-sid-mutes').onclick=e=>{const b=e.target.closest('[data-sid-mute]');if(!b)return;const i=+b.dataset.sidMute;set.sid.voices[i].mute=!set.sid.voices[i].mute;local.sid.setProject(set.sid);send('sidMute',{voice:i,mute:set.sid.voices[i].mute});renderLive();persist();};$('live-paula-mutes').onclick=e=>{const b=e.target.closest('[data-p-mute]');if(!b)return;const i=+b.dataset.pMute;paulaParam(i,'mute',!set.paula.channels[i].mute);renderChannels();renderLive();};
function setMix(key,value){set.mix[key]=value;local.setMix({[key]:value});send('mix',{patch:{[key]:value}});renderMix();persist();}$('crossfade').oninput=()=>setMix('crossfade',+$('crossfade').value/100);$('master').oninput=()=>setMix('master',+$('master').value/100);$('tone').oninput=()=>setMix('tone',+$('tone').value);$('solo-sid').onclick=()=>setMix('crossfade',0);$('blend').onclick=()=>setMix('crossfade',.5);$('solo-paula').onclick=()=>setMix('crossfade',1);
async function launchScene(slot){stopPreview();if(!scenes[slot])return;try{await audio();releaseAll();const data=clone(scenes[slot].set);data.bpm=data.sid.bpm=data.paula.bpm=set.bpm;const token=`${slot}:${++sceneSerial}`;pendingScene={slot,set:data,token};send('scene',{set:data,id:token});renderScenes();$('scene-state').textContent=`SZENE ${slot+1} WARTET AUF TAKT 1`;}catch(e){toast(e.message);}}
$('scenes').onclick=e=>{const a=e.target.closest('[data-launch]'),b=e.target.closest('[data-store]');if(a)launchScene(+a.dataset.launch);if(b){const i=+b.dataset.store;scenes[i]={name:set.paula.name.replace(/^\d+ · /,''),set:clone(set)};activeScene=i;renderScenes();persist();toast(`Szene ${i+1} gespeichert.`);}};
$('stage-mode').onclick=async()=>{stage=!stage;document.body.classList.toggle('stage',stage);$('stage-mode').textContent=stage?'Studioansicht ↙':'Bühnenansicht ↗';if(stage){setView('live');try{await document.documentElement.requestFullscreen?.();}catch{}}else if(document.fullscreenElement)await document.exitFullscreen?.().catch(()=>{});};
$('record').onclick=async()=>{stopPreview();try{await audio();if(recording){send('recordStop');return;}recordChunks=[];recording=true;updateRecord(0);send('recordStart');if(!playing){send('play');playing=true;updateTransport();}toast('Aufnahme läuft. REC beendet und speichert den Take.');}catch(e){recording=false;updateRecord(0);toast(e.message);}};
function renderCPU(){const p=state.paula,c=p.cpu,regs=[['D0',c.d[0]],['D1',c.d[1]],['A0',c.a[0]],['A1',c.a[1]],['PC',c.pc],['SR',c.sr]];$('paula-registers').innerHTML=regs.map(([n,v])=>`<div class="register-cell">${n}<strong>$${h68(v,n==='SR'?4:8)}</strong></div>`).join('');$('paula-instr').textContent=c.instructions.toLocaleString('de-DE')+' INSTR.';$('paula-trace').innerHTML=c.trace.map(t=>`<div class="trace-row"><span>${h68(t.pc,4)}</span><span>${h68(t.opcode,4)}</span><span>${esc(t.text)}</span></div>`).join('');$('paula-dma').textContent='DMA $'+h68(p.dma,4);$('paula-hardware').innerHTML=p.channels.map((ch,i)=>`<div class="hardware-row ${ch.active?'on':''}"><div><small>AUD${i}</small><strong>${ch.active?'● ON':'○ OFF'}</strong></div><div><small>POINTER / LENGTH</small>$${h68(ch.pointer,6)} / ${ch.length}</div><div><small>PERIOD / VOL</small>${ch.period} / ${ch.volume}</div></div>`).join('');}
$('paula-step').onclick=()=>{try{releaseAll();if(node)send('step');else{local.stop();local.paula.debugStep();state=local.snapshot();updateState();}}catch(e){toast(e.message);}};
$('paula-compile').onclick=()=>{try{const source=$('paula-code').value,p=assemble68(source);local.paula.load(source);set.paula.source=source;send('load',{source});$('paula-compile-status').textContent=`${p.writes.length} Bytes geladen · PLAY $${h68(p.entry,4)}.`;persist();if(!node){state=local.snapshot();renderCPU();}toast('68000-Maschinencode geladen.');}catch(e){$('paula-compile-status').textContent=e.message;toast(e.message);}};$('paula-restore').onclick=()=>{$('paula-code').value=PAULA_DRIVER;$('paula-compile').click();};$('paula-code').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();e.target.setRangeText('  ',e.target.selectionStart,e.target.selectionEnd,'end');}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();$('paula-compile').click();}};
function download(data,type,name){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
$('export-set').onclick=()=>download(JSON.stringify(bundle()),'application/json','Small-Machines-Set.json');$('import-set').onclick=()=>$('set-file').click();$('set-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>12000000)throw Error('Setdatei zu groß (max. 12 MB).');const b=validateBundle(JSON.parse(await f.text()));stopPreview();releaseAll();set=clone(b.set);scenes=clone(b.scenes);local=new Rack(44100,set);send('set',{set});playing=false;activeScene=null;pendingScene=null;state=local.snapshot();renderAll();persist();toast('Set und Szenen geladen.');}catch(e){toast(e.message);}finally{e.target.value='';}};
