$('sample-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>8000000)throw Error('Bitte einen kurzen Sound bis 8 MB verwenden.');await audio();const decoded=await audioContext.decodeAudioData(await f.arrayBuffer());if(decoded.duration>2.001)throw Error('Bitte einen Ausschnitt von höchstens 2 Sekunden laden.');if(decoded.duration<.001)throw Error('Sample ist leer.');const rate=16000,length=Math.max(2,Math.ceil(decoded.duration*rate/2)*2),Offline=window.OfflineAudioContext||window.webkitOfflineAudioContext;if(!Offline)throw Error('OfflineAudioContext ist hier nicht verfügbar.');const offline=new Offline(1,length,rate),source=offline.createBufferSource();source.buffer=decoded;source.connect(offline.destination);source.start();const rendered=await offline.startRendering(),data=rendered.getChannelData(0),pcm=Array.from(data,x=>Math.round(Math.max(-1,Math.min(1,x))*127));set.paula.custom[uploadChannel]={name:f.name.replace(/\.[^.]+$/,'').slice(0,60),rate,root:60,pcm};stopPreview();releaseAll();send('noteOff',{voice:uploadChannel});local.paula.noteOff(uploadChannel);assignSample(set.paula,uploadChannel,'custom'+uploadChannel);updatePaula(true);renderChannels();toast('Eigener Sound geladen: Mono, 16 kHz, 8 Bit. Originaltempo bei C4.');}catch(e){toast(e.message);}finally{e.target.value='';}};
function attachMIDI(){for(const input of midiAccess.inputs.values()){input.onmidimessage=e=>{const [status,n,value]=e.data,type=status&0xf0,channel=status&15,token='m'+input.id+':'+channel+':'+n;if(type===0x90&&value>0)press(token,n);else if(type===0x80||type===0x90&&value===0)release(token);else if(type===0xb0&&n===1)setMix('crossfade',value/127);else if(type===0xb0&&(n===120||n===123))releaseAll();};}$('midi-state').textContent=`${midiAccess.inputs.size} MIDI-Eingang/Eingänge · Noten → Kanal ${selected+1} · CC 1 → Crossfader`;}
