const canvas=$('rack-scope'),context=canvas.getContext('2d');let animation=0;function draw(){requestAnimationFrame(draw);if(document.hidden||++animation%2)return;const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);}const w=canvas.width,h=canvas.height;context.clearRect(0,0,w,h);context.strokeStyle='#2c3942';context.lineWidth=1;context.beginPath();for(let i=0;i<=12;i++){context.moveTo(w*i/12,0);context.lineTo(w*i/12,h);}for(let i=0;i<=6;i++){context.moveTo(0,h*i/6);context.lineTo(w,h*i/6);}context.stroke();if(analyser)analyser.getFloatTimeDomainData(scopeData);else scopeData.fill(0);let start=0;for(let i=1;i<scopeData.length/2;i++)if(scopeData[i-1]<0&&scopeData[i]>=0){start=i;break;}context.beginPath();for(let i=0;i<768;i++){const x=i/767*w,y=h*.5-scopeData[(start+i)%scopeData.length]*h*.7;if(!i)context.moveTo(x,y);else context.lineTo(x,y);}context.strokeStyle='#aac5d6';context.lineWidth=1.3*dpr;context.shadowColor='#729ab6';context.shadowBlur=7*dpr;context.stroke();context.shadowBlur=0;$('meter-left').style.width=Math.min(100,Math.sqrt(outputPeaks[0])*100)+'%';$('meter-right').style.width=Math.min(100,Math.sqrt(outputPeaks[1])*100)+'%';}
